sub(p,'/** Includes archived slugs','''/** Number of live issues a clone of `projectId` would copy. */
export async function countLiveIssuesForClone(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export type ClonedProject = {
  readonly project: Project;
  readonly issues: readonly Issue[];
};

/**
 * Writes a clone in one transaction: the new project (with the source's
 * description, visibility, colour and lead; active, undated, not archived) and,
 * when asked, a fresh copy of every live source issue. Copies keep title,
 * description, priority, estimate, due date and labels; they start in
 * `issueStatus`, unassigned, unstarted, authored by `authorId`, and are
 * numbered from 1 in the order of the source numbers. Either everything is
 * written or nothing is.
 */
export function insertProjectClone(
  source: Project,
  target: { name: string; slug: string; key: string },
  options: {
    includeIssues: boolean;
    issueStatus: IssueStatus;
    authorId: UserId;
  },
): ClonedProject {
  return getDb().transaction((tx) => {
    const taken = tx
      .select({ slug: projects.slug })
      .from(projects)
      .where(orgPredicate(projects.orgId, source.orgId))
      .all()
      .map((row) => row.slug);
    const stamp = toIsoTimestamp(new Date());

    const projectRow = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: source.orgId,
        name: target.name,
        slug: uniqueSlug(target.slug, taken),
        key: target.key,
        description: source.description,
        visibility: source.visibility,
        status: "active",
        leadId: source.leadId,
        color: source.color,
        startsAt: null,
        targetDate: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    const copies: Issue[] = [];
    if (options.includeIssues) {
      const liveSource = and(
        orgPredicate(issues.orgId, source.orgId),
        eq(issues.projectId, source.id),
        isNull(issues.archivedAt),
      );
      const sourceIssues = tx
        .select()
        .from(issues)
        .where(liveSource)
        .orderBy(issues.number)
        .all();

      const labelsBySource = new Map<string, LabelId[]>();
      for (const link of tx
        .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, source.orgId),
            inArray(
              issueLabels.issueId,
              tx.select({ id: issues.id }).from(issues).where(liveSource),
            ),
          ),
        )
        .all()) {
        const bucket = labelsBySource.get(link.issueId) ?? [];
        bucket.push(link.labelId as LabelId);
        labelsBySource.set(link.issueId, bucket);
      }

      sourceIssues.forEach((original, index) => {
        const row = tx
          .insert(issues)
          .values({
            id: newId(),
            orgId: source.orgId,
            projectId: projectRow.id,
            number: index + 1,
            title: original.title,
            description: original.description,
            status: options.issueStatus,
            priority: original.priority,
            authorId: options.authorId,
            assigneeId: null,
            parentId: null,
            estimate: original.estimate,
            dueAt: original.dueAt,
            startedAt: null,
            completedAt: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .returning()
          .get();

        const labelIds = labelsBySource.get(original.id) ?? [];
        if (labelIds.length > 0) {
          tx.insert(issueLabels)
            .values(
              labelIds.map((labelId) => ({
                orgId: source.orgId,
                issueId: row.id,
                labelId,
              })),
            )
            .run();
        }
        copies.push(toIssue(row, labelIds));
      });
    }

    return { project: toProject(projectRow), issues: copies };
  });
}

/** Includes archived slugs''')
