sub(p,'export async function updateProject(','''/**
 * Clones a project into a new one of the same workspace (ADR 0012). Gated like
 * a creation: read on the source, create on the workspace, the project quota,
 * and — for the whole batch at once — the per-project issue quota. Nothing is
 * written unless every gate passes, and the project and its issue copies are
 * written together. Publishes `project.cloned` only; the search index and the
 * usage meters, which `project.created` / `issue.created` would have driven,
 * are brought up to date here.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  if (input.includeIssues) {
    const toCopy = await projectRepo.countLiveIssuesForClone(
      input.orgId,
      source.id,
    );
    if (wouldExceedLimit(org.plan, "issuesPerProject", 0, toCopy)) {
      throw new Error(
        `Plan ${org.plan} allows no more issues in project ${input.key}`,
      );
    }
  }

  const configuredStatus = org.settings.defaultIssueStatus as IssueStatus;
  const { project, issues } = projectRepo.insertProjectClone(
    source,
    { name: input.name, slug: input.slug, key: input.key },
    {
      includeIssues: input.includeIssues,
      issueStatus: ISSUE_STATUSES.includes(configuredStatus)
        ? configuredStatus
        : "backlog",
      authorId: actor.userId,
    },
  );

  await indexProject(input.orgId, project);
  for (const issue of issues) await indexIssue(input.orgId, issue);
  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: issues.length,
  });

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: issues.length,
  });

  return project;
}

export async function updateProject(''')
